def save(store, workspace, operation_id, values):
    record = next((item for item in store.recovery.values()
                   if item["workspace"] == workspace), None)
    if record is None:
        record = {"operation_id": operation_id, "workspace": workspace,
                  "status": "pending", "values": dict(values)}
        store.recovery[operation_id] = record
    if record["status"] == "pending":
        store.apply(workspace, record["values"])
        record["status"] = "applied"
    store.receipt(record)
    return {"ok": True, "operation_id": operation_id}

from service import save


def submit(store, workspace, operation_id, values):
    return save(store, workspace, operation_id, values)

class ReceiptUnavailable(Exception):
    pass


class Store:
    def __init__(self):
        self.preferences = {}
        self.recovery = {}
        self.fail_receipt_once = False

    def apply(self, workspace, values):
        self.preferences[workspace] = dict(values)

    def receipt(self, record):
        if self.fail_receipt_once:
            self.fail_receipt_once = False
            raise ReceiptUnavailable("receipt store unavailable")
        record["status"] = "completed"
        return {"ok": True, "operation_id": record["operation_id"]}
